using System;using System.IO;using System.Text;using System.Collections;using System.Linq;using UnityEngine;using LWS.TruckSports;using LWS.TruckBowling;
namespace LWS.TruckFieldGoal {
public sealed class FieldGoalProbe:MonoBehaviour {
#if UNITY_EDITOR || DEVELOPMENT_BUILD
 [RuntimeInitializeOnLoadMethod]static void Boot(){bool run=Array.IndexOf(Environment.GetCommandLineArgs(),"-tsFieldGoal")>=0;
#if UNITY_EDITOR
 run|=UnityEditor.SessionState.GetBool("LWS.FieldGoal",false);UnityEditor.SessionState.SetBool("LWS.FieldGoal",false);
#endif
 if(run){var root=new GameObject("Field Goal bumper kicks and full AI match acceptance");DontDestroyOnLoad(root);if(FindAnyObjectByType<SportsProbeInputIsolation>()==null)root.AddComponent<SportsProbeInputIsolation>();root.AddComponent<FieldGoalProbe>();}}
 IDisposable preferences;void Awake(){preferences=SportsPrefs.IsolateValidation("FieldGoalMatch");SportsParticipantRegistry.ForgetCache();}
 string folder;int errors;readonly StringBuilder report=new StringBuilder();void Check(bool ok,string label){report.AppendLine((ok?"PASS ":"FAIL ")+label);if(!ok)errors++;Write();}void Write(){File.WriteAllText(folder+"/progress.txt",report.ToString());}void Error(string s,string stack,LogType type){if(type==LogType.Error||type==LogType.Exception){errors++;report.AppendLine("ERROR "+s+"\n"+stack);Write();}}
 IEnumerator Capture(FieldGoalMatch match,int variant){var camera=match.cameraRig.view;var rt=new RenderTexture(1280,720,24);rt.Create();var old=camera.targetTexture;var active=RenderTexture.active;camera.targetTexture=rt;camera.aspect=16f/9;yield return null;camera.Render();RenderTexture.active=rt;var picture=new Texture2D(1280,720,TextureFormat.RGB24,false);picture.ReadPixels(new Rect(0,0,1280,720),0,0);picture.Apply();File.WriteAllBytes(folder+"/variant-"+variant+"-flight-camera-only.png",picture.EncodeToPNG());Destroy(picture);camera.targetTexture=old;camera.ResetAspect();RenderTexture.active=active;rt.Release();Destroy(rt);}
 IEnumerator Start(){folder=SportsEvidencePaths.Folder("FieldGoalEvidence");File.WriteAllText(folder+"/result.txt","RUNNING "+DateTime.UtcNow.ToString("O"));Application.logMessageReceived+=Error;yield return SportsProbeScene.Ensure<FieldGoalMatch>("TruckFieldGoal");var m=FindAnyObjectByType<FieldGoalMatch>();m.weatherPresets.Select(m.weatherPresets.entries.First(p=>p.displayName=="Clear").id);yield return null;foreach(int variant in new[]{0})for(int difficulty=0;difficulty<3;difficulty++){m.SetupScreen();m.option=variant;m.setup.count=4;m.NormalizeSetup();m.AllBots();for(int i=0;i<4;i++)m.setup.players[i].difficulty=(BowlingDifficulty)difficulty;m.seed=18361+difficulty*7919;var audience=m.GetComponent<FieldGoalCrowd>();int previousReactions=audience!=null?audience.Reactions:0;Check(audience!=null&&audience.Spectators>=500&&audience.nearFans.Length<=40,"saved populated stadium uses bounded live animators and pooled instanced audience");Check(m.StartMatch(),"four-AI full physical match starts variant="+variant+" difficulty="+difficulty);Time.timeScale=10;float deadline=Time.realtimeSinceStartup+240,next=0;int round=0,current=-1,launches=0,good=0;bool replay=false,captured=false,wasLaunched=false;while(!m.Finished&&Time.realtimeSinceStartup<deadline){if(m.rules.Round!=round||m.rules.Current!=current){round=m.rules.Round;current=m.rules.Current;wasLaunched=false;report.AppendLine("ATTEMPT variant="+variant+" round="+round+" current="+current+" goals="+string.Join(",",m.rules.goals));Write();}if(m.Projectile.LaunchObserved&&!wasLaunched){launches++;wasLaunched=true;report.AppendLine("REAL_KICK v="+m.Projectile.LaunchVelocity.ToString("F3")+" timing="+m.Timing.ToString("F3"));Write();}good=m.rules.goals.Sum();replay|=m.Phase==FieldGoalPhase.Replay;if(!captured&&difficulty==0&&m.Phase==FieldGoalPhase.Flight&&m.FlightAge>.5f){yield return Capture(m,variant);captured=true;}if(Time.realtimeSinceStartup>=next){File.WriteAllText(folder+"/live.txt","variant="+variant+" difficulty="+difficulty+" round="+round+" current="+current+" phase="+m.Phase+" phaseAge="+m.PhaseAge+" pos="+m.truck.body.position+" ball="+m.football.Reference+" velocity="+m.Projectile.body.linearVelocity+" command="+m.truck.command+" goals="+string.Join(",",m.rules.goals)+" errors="+errors);next=Time.realtimeSinceStartup+2;}if(round>10&&good==0){Check(false,"all-zero trajectories cannot loop through endless tiebreaks");break;}yield return null;}
 Check(m.Finished&&m.rules.Winner>=0,"complete real five-attempt match and equal-opportunity extras variant="+variant+" difficulty="+difficulty);Check(m.rules.attempts.All(x=>x>=5),"everyone gets five deliveries");Check(launches>10&&good>0,"actual contacts produce physical launches and legal forward goals");Check(replay,"actual recorded replay advances automatically");Check(audience.Reactions-previousReactions==m.rules.attempts.Sum(),"exactly one crowd reaction per actual locked physical attempt");report.AppendLine("MATCH variant="+variant+" difficulty="+difficulty+" goals="+string.Join(",",m.rules.goals)+" attempts="+string.Join(",",m.rules.attempts)+" rounds="+m.rules.Round+" launches="+launches+" winner="+m.rules.Winner);Write();if(errors>0)goto Complete;}
 Complete:m.SetupScreen();report.AppendLine("ERRORS="+errors+". Real NWH approach, contact-derived bumper kick, PhysX flight, goal crossing and recorded replay. No human/hardware/audio or Windows/GPU benchmark claim.");File.WriteAllText(folder+"/result.txt",report.ToString());Debug.Log("FIELD_GOAL_PROBE_COMPLETE "+report);Application.logMessageReceived-=Error;Time.timeScale=1;
#if UNITY_EDITOR
 if(Application.isEditor)UnityEditor.EditorApplication.isPlaying=false;else
#endif
 Application.Quit(errors==0?0:2);}
 void OnDestroy(){Application.logMessageReceived-=Error;preferences?.Dispose();SportsParticipantRegistry.ForgetCache();Time.timeScale=1;}
#endif
}
